          'જૂથમાં વહેંચેલી કે નેસ્ટ કરેલી હરોળ ટેબલને <code>treegrid</code> બનાવે છે: હરોળમાં <code>aria-level</code>, <code>aria-setsize</code> અને <code>aria-posinset</code> હોય છે, અને ખૂલી શકતી હરોળમાં <code>aria-expanded</code>. ઍગ્રિગેટ તેના પ્રકાર સાથે વંચાય છે, જેમ કે “Sum: 475”.',
